/**
 * Attachment bytes: where they live, how they get there, and how they come back.
 *
 * The bytes are files on disk, not blobs in the database. That is the whole
 * design: SQLite as a single file stays a database you can copy in a second, and
 * a 20 MB PDF does not turn every backup and every `select` into a liability. The
 * cost is that two things have to agree — the row and the file — so every write
 * here is ordered to fail in the safe direction (see `save`).
 *
 * Everything below the repository is a `storageKey`: `<userId>/<attachmentId>`,
 * generated by us from ids we already own. No part of it comes from the uploaded
 * file's name, so a name like `../../etc/passwd` is stored as a *label* and never
 * becomes a path. `resolve()` re-checks that, because the cheapest defence is the
 * one that cannot be forgotten.
 */
import fs from 'node:fs/promises';
import path from 'node:path';
import { getEnv } from '@/lib/env';
import { MAX_ATTACHMENT_BYTES } from '@/lib/attachments';
import type { Attachment } from '@/lib/types';
import { newId } from '../crypto';
import { currentDialect, sqliteFilePath } from '../db/dialect';
import {
  createAttachment,
  deleteAttachment,
  getAttachmentWithStorage,
  listAttachments,
  type AttachmentOwner,
  type AttachmentWithStorage,
} from '../repos/attachments';

/** An uploaded file as the route hands it over: the name, the type, the bytes. */
export interface IncomingFile {
  filename: string;
  mimeType: string;
  bytes: Uint8Array;
}

/** Thrown when an upload should become a 4xx, with a message worth showing. */
export class AttachmentError extends Error {
  constructor(
    message: string,
    readonly status: number,
  ) {
    super(message);
    this.name = 'AttachmentError';
  }
}

/**
 * The attachments directory, absolute, created on first use.
 *
 * Unset means "beside the SQLite file" rather than a fixed relative path: the
 * database already lives on the data volume, so its folder is the one directory
 * that is certainly persistent. A hard-coded `./data/attachments` would resolve
 * against the container's working directory, which is *not* that volume — every
 * upload would vanish on the next container rebuild.
 *
 * With Postgres there is no such file to sit beside, so the fallback is a folder
 * in the working directory and the deployer has to point this somewhere shared
 * (see .env.example).
 */
export function attachmentsDir(): string {
  const configured = getEnv().ATTACHMENTS_DIR.trim();
  if (configured) return path.resolve(configured);
  if (currentDialect() === 'sqlite') return path.resolve(path.dirname(sqliteFilePath()), 'attachments');
  return path.resolve('data/attachments');
}

/** `<userId>/<attachmentId>` — derived from ids only, never from the file name. */
export function storageKeyFor(userId: string, attachmentId: string): string {
  return `${userId}/${attachmentId}`;
}

/**
 * Absolute path for a key, refusing anything that escapes the root.
 *
 * A key that resolves outside its root is a bug or an attack, and either way the
 * right answer is to throw rather than to read the file it points at.
 */
function pathFor(storageKey: string): string {
  const root = attachmentsDir();
  const full = path.resolve(root, storageKey);
  const relative = path.relative(root, full);
  if (!relative || relative.startsWith('..') || path.isAbsolute(relative)) {
    throw new Error(`Refusing attachment storage key outside the attachment root: ${storageKey}`);
  }
  return full;
}

/**
 * Rewrites an uploaded name into something safe to show and safe to serve.
 *
 * A browser sends the file's *base name*, but nothing stops a client from sending
 * anything: separators, control characters, a kilometre of text. We keep the name
 * legible — it is what the user recognises the file by — while removing what would
 * break a header, a log line or a filesystem.
 */
export function cleanFilename(raw: string): string {
  const base = raw.split(/[\\/]/).pop() ?? '';
  // eslint-disable-next-line no-control-regex
  const stripped = base.replace(/[\u0000-\u001f\u007f]/g, '').trim();
  if (!stripped) return 'attachment';
  return stripped.length > 180 ? stripped.slice(0, 180) : stripped;
}

/** Writes one file. Bytes first, in a directory that is created on demand. */
async function writeBytes(storageKey: string, bytes: Uint8Array): Promise<void> {
  const file = pathFor(storageKey);
  await fs.mkdir(path.dirname(file), { recursive: true });
  await fs.writeFile(file, bytes);
}

async function readBytes(storageKey: string): Promise<Uint8Array | null> {
  try {
    return await fs.readFile(pathFor(storageKey));
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null;
    throw error;
  }
}

async function removeBytes(storageKey: string): Promise<void> {
  await fs.rm(pathFor(storageKey), { force: true });
}

/**
 * Stores an upload and records it against its owner.
 *
 * Order matters. The bytes are written *before* the row, so a failure leaves an
 * unreferenced file — wasted disk, invisible to every query — instead of a row
 * that promises a download which 500s. On a failed insert the file is removed
 * again on a best-effort basis, and if that cleanup is what fails, the orphan is
 * still the recoverable kind of wrong.
 */
export async function saveAttachment(
  userId: string,
  owner: AttachmentOwner,
  file: IncomingFile,
): Promise<Attachment> {
  const bytes = file.bytes;
  if (bytes.byteLength === 0) throw new AttachmentError('That file is empty.', 400);
  if (bytes.byteLength > MAX_ATTACHMENT_BYTES) {
    throw new AttachmentError(
      `That file is ${Math.round(bytes.byteLength / (1024 * 1024))} MB. The limit is ${Math.round(
        MAX_ATTACHMENT_BYTES / (1024 * 1024),
      )} MB per file.`,
      413,
    );
  }

  const id = newId();
  const storageKey = storageKeyFor(userId, id);
  await writeBytes(storageKey, bytes);
  try {
    return await createAttachment(userId, {
      ...owner,
      id,
      filename: cleanFilename(file.filename),
      mimeType: file.mimeType || 'application/octet-stream',
      sizeBytes: bytes.byteLength,
      storageKey,
    });
  } catch (error) {
    await removeBytes(storageKey).catch(() => undefined);
    throw error;
  }
}

/** A task's or an event's files, newest last. */
export function listOwnedAttachments(userId: string, owner: AttachmentOwner): Promise<Attachment[]> {
  return listAttachments(userId, owner);
}

/**
 * Everything needed to serve one download, or null when the caller may not see it.
 *
 * The row goes first: it is the permission check, and only after it passes is the
 * disk touched. A missing file is reported as null too — the row without bytes is
 * an inconsistency, and answering 404 is honest about a download that cannot work,
 * whereas a 500 would suggest the server is broken.
 */
export async function readAttachment(
  userId: string,
  id: string,
): Promise<{ attachment: AttachmentWithStorage; bytes: Uint8Array } | null> {
  const attachment = await getAttachmentWithStorage(userId, id);
  if (!attachment) return null;
  const bytes = await readBytes(attachment.storageKey);
  if (!bytes) return null;
  return { attachment, bytes };
}

/**
 * Removes the row, then the bytes.
 *
 * This order is the mirror of the write, and for the same reason: a row that is
 * gone while its file lingers leaks disk, while a file that is gone with its row
 * still present is a download that fails forever. The database is the source of
 * truth, so it goes first.
 */
export async function deleteOwnedAttachment(userId: string, id: string): Promise<boolean> {
  const removed = await deleteAttachment(userId, id);
  if (!removed) return false;
  await removeBytes(removed.storageKey).catch(() => undefined);
  return true;
}

/**
 * `Content-Disposition` that survives a non-ASCII name.
 *
 * Headers are latin-1, so a name with an accent cannot go in the quoted form. The
 * ASCII fallback keeps old clients working; `filename*=UTF-8''…` is what modern
 * browsers actually use and what makes "Résumé.pdf" arrive as "Résumé.pdf".
 */
export function contentDisposition(filename: string): string {
  return disposition('attachment', filename);
}

/**
 * The same header for a file the browser should show rather than save.
 *
 * A preview is an `<img>`, an `<iframe>` or a `fetch` of the same URL, and all
 * three honour `Content-Disposition: attachment` by downloading instead — so the
 * preview asks for `?inline=1` and gets the identical bytes under a header that
 * lets it draw. The download path keeps `attachment`, because a click on
 * "Download" that renders a PDF in place is not a download.
 */
export function inlineContentDisposition(filename: string): string {
  return disposition('inline', filename);
}

function disposition(kind: 'attachment' | 'inline', filename: string): string {
  const ascii = filename.replace(/[^\x20-\x7e]/g, '_').replace(/["\\]/g, '_');
  return `${kind}; filename="${ascii}"; filename*=UTF-8''${encodeURIComponent(filename)}`;
}
